def _update_completion_gate(notebook: dict) -> None:
    cell = _find_cell(notebook, "remaining-final-gate")
    source = "".join(cell.get("source", []))
    source = source.replace(
        "# Completion gate - all planned stages are implemented",
        "# Completion gate - bounded implementation stages are in place",
        1,
    )
    source = source.replace(
        "- Implemented and smoke-tested: all stages.",
        "- Implemented and bounded-smoke-tested: GenMol Stages 0-18 and UDLM Stage 20.",
        1,
    )
    source = _replace_required(
        source,
        "- Cross-rank loss uses a global numerator and denominator, inference uses EMA weights, and MCG logit normalization equivalence is stated.",
        "- Stage 8 teaches an exact-global numerator/denominator reduction as a labeled repair; the faithful/current training path keeps released process-local token ratios, which DDP and accumulation average. Inference uses EMA weights, and MCG logit-normalization equivalence is stated.",
        label="completion-gate distributed loss qualification",
    )
    marker = "\n## UDLM extension status"
    if marker in source:
        source = source.split(marker, 1)[0].rstrip()
    udlm_note = f"""

## UDLM extension status

- Stage 20 derives the uniform forward law, normalized reverse posterior, and
  full content-position objective, then cross-checks notebook-native functions
  against production diffusion and time-conditioning code.
- The released residual-clean corruption schedule and idealized loss schedule
  are deliberately distinguished; the paper's zero-prior-loss statement does
  not hold exactly for the implemented residual-clean endpoint.
- Two pinned seed-1 CPU toy artifacts at implementation base
  `{UDLM_BASE_COMMIT}` are linked, hashed, and schema-validated. They are bounded
  integration evidence, not evidence that UDLM beats GenMol.
- A clean-source CPU audit of ordered training rows 10,001--30,000 recommends
  empirical floor 0.0002 for reviewed pilots. The rule was formalized after
  inspecting those blocks, so it is retrospective training-only engineering,
  not confirmatory or molecular-quality evidence; historical/manual artifacts
  remain at 0.01.
- Candidate training must bind launch-manifest schema 2, runtime schema 2,
  summary schema 4, and receipt schema 5, including the exact selected UUIDs,
  final-idle telemetry, repository-global single-job lease, and exact R/S/E
  predecessor artifacts. The lease machine-enforces one-job concurrency; the
  genesis/predecessor chain independently machine-enforces registered order.
- `launch_health_panel.py` fixes the exact seed-1, full-vocabulary, MDLM-EMA
  10-update contract and deterministic `health-w{{W}}-{{r,s,e}}-{{H}}` names;
  `validate_health_panel.py` grants screen authorization only. Its terminal-E
  receipt is required independently before config materialization and registry
  freezing and cannot satisfy the later candidate lock.
- The prospective small-first ladder continues with an E-only 100-update
  scheduler screen, an E-only 500-update conditioning screen, then selected
  matched R/S/E runs at 1,000 updates. Only after those training runs, seed
  1100 x 32 requests is an ineligible decode diagnostic; only seeds 1000/1001 x
  256 requests at 128 NFE may select.
- Completed selection seeds publish schema-2 reference-only envelopes after
  structural validation and fresh-process raw-text rescoring. Failed seeds use
  launcher-authored schema-1 receipts; a partial failure retains the completed
  sibling while making the attempt ineligible. All outcomes must predate the
  lock and descend into the final benchmark revision.
- CPU plumbing exists for the two prospective screens, but their exact arm
  registry is not frozen, the reviewed launcher does not authorize them, and
  no GPU screen has run. L1 is an optimizer-schedule bundle with about 37.57x
  L0's cumulative learning-rate exposure over updates 0--99, not an isolated
  cosine-shape ablation. Both 500-update A0/A1 arms must independently reload
  the same MDLM EMA and reseed after initialization; A1 is the outer-SiLU,
  zero-FiLM warm-start hypothesis with staged conditioner gradients.
- The final success gate is three matched 1,000-request seeds with repaired and
  strict metrics, checkpoint/seeds/device/runtime provenance, independent
  raw-text rescoring of all three CSVs, and thresholds recorded in
  `stage20_success_criteria`.
- Final checkpoint: why is clean-logit interpolation not valid UDLM
  classifier-free guidance? Expected reasoning: clean probabilities are
  transformed nonlinearly into the reverse posterior, so guidance must combine
  conditional and unconditional reverse-posterior log probabilities.
"""
    cell["source"] = source + udlm_note


def update_notebook(source: Path, destination: Path):
    notebook = json.loads(source.read_text())
    replacement_cells = stage_cells()
    _validate_stage20_cells(notebook["cells"], replacement_cells)
    _update_stage0(notebook)
    _update_report(notebook)
    _update_completion_gate(notebook)
    replacement_ids = {cell["id"] for cell in replacement_cells}
    notebook["cells"] = [
        cell for cell in notebook["cells"] if cell.get("id") not in replacement_ids
    ]
    insert_at = next(
        index
        for index, cell in enumerate(notebook["cells"])
        if cell.get("id") == "stage19-report-note"
        or any(
            str(tag).startswith(STAGE_TAG_PREFIX)
            for tag in cell.get("metadata", {}).get("tags", [])
        )
    )
    notebook["cells"][insert_at:insert_at] = replacement_cells
    # Stage 0 changes the device count, source checkout, and provenance state.
    # Every prior saved execution is therefore stale, including downstream
    # tables and launch commands that were produced with three GPUs.  Keep the
    # teaching artifact honest and clean-kernel executable by clearing all
    # outputs and execution timestamps; committed result artifacts remain the
    # source of bounded numerical evidence.
    for cell in notebook["cells"]:
        if cell.get("cell_type") == "code":
            cell["execution_count"] = None
            cell["outputs"] = []
            cell.setdefault("metadata", {}).pop("execution", None)
    destination.write_text(json.dumps(notebook, indent=1, ensure_ascii=False) + "\n")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    update_notebook(args.source, args.destination)


if __name__ == "__main__":
    main()
